/**
 ******************************************************************************
 * @file    test_charger_status.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   Unit tests for the charger/gauge status-pin decoder.
 *
 * Owner: Brendon Bone (PD5b).
 *
 * Coverage: steady-level decodes for every PG/STAT combination, the 1 Hz
 * STAT fault-blink detector (nominal, jittered, too fast, too slow, and
 * recovery when the blink stops), the ALERT latch semantics, VBUS handling
 * with and without a VBUS reader, pin-read failures, and a full multi-step
 * charge-cycle scenario walking the state machine end to end.
 ******************************************************************************
 */
#include "unity.h"
#include "charger_status.h"
#include "mock_pins.h"

#include <string.h>

static Charger_Monitor s_mon;

void setUp(void)
{
    MockPins_Reset();
    memset(&s_mon, 0, sizeof(s_mon));
    TEST_ASSERT_EQUAL(CHARGER_OK, Charger_Init(&s_mon, MockPins_Iface()));
}

void tearDown(void)
{
}

/* Tick helper with explicit time, asserting the sample succeeded. */
static void tick_ok(uint32_t t)
{
    TEST_ASSERT_EQUAL(CHARGER_OK, Charger_Tick(&s_mon, t));
}

/* Drive a 1 Hz STAT blink: toggle the level every `half_ms`, sampling every
 * `step_ms`, starting at *t. Returns the time after `edges` toggles. */
static uint32_t drive_blink(uint32_t *t, uint32_t half_ms, uint32_t step_ms,
                            int start_level, uint32_t edges)
{
    uint32_t e;
    int level = start_level;

    MockPins_SetStat(level);
    tick_ok(*t);

    for (e = 0U; e < edges; e++) {
        uint32_t target = *t + half_ms;

        /* sample (without a toggle) until the next edge time */
        while (*t + step_ms < target) {
            *t += step_ms;
            tick_ok(*t);
        }
        *t = target;
        level = (level == 0) ? 1 : 0;
        MockPins_SetStat(level);
        tick_ok(*t);
    }
    return *t;
}

/* -------------------------------------------------------------------------- */
/* Initialisation and parameter validation                                     */
/* -------------------------------------------------------------------------- */

static void test_init_rejects_bad_params(void)
{
    Charger_Pins bad;

    TEST_ASSERT_EQUAL(CHARGER_ERR_PARAM, Charger_Init(NULL, MockPins_Iface()));
    TEST_ASSERT_EQUAL(CHARGER_ERR_PARAM, Charger_Init(&s_mon, NULL));

    memset(&bad, 0, sizeof(bad));   /* all readers missing */
    TEST_ASSERT_EQUAL(CHARGER_ERR_PARAM, Charger_Init(&s_mon, &bad));
}

static void test_state_unknown_before_first_tick(void)
{
    TEST_ASSERT_EQUAL(CHARGER_STATE_UNKNOWN, Charger_GetState(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsPowerGood(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_AlertPending(&s_mon));
}

static void test_tick_rejects_null(void)
{
    TEST_ASSERT_EQUAL(CHARGER_ERR_PARAM, Charger_Tick(NULL, 0U));
}

/* -------------------------------------------------------------------------- */
/* Steady-level decode (open-drain: LOW = asserted)                            */
/* -------------------------------------------------------------------------- */

static void test_pg_low_stat_low_decodes_charging(void)
{
    MockPins_SetPg(0);
    MockPins_SetStat(0);
    tick_ok(0U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_CHARGING, Charger_GetState(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_IsPowerGood(&s_mon));
}

static void test_pg_low_stat_high_decodes_complete(void)
{
    MockPins_SetPg(0);
    MockPins_SetStat(1);
    tick_ok(0U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_COMPLETE_OR_DISABLED,
                      Charger_GetState(&s_mon));
}

static void test_pg_high_decodes_no_input_regardless_of_stat(void)
{
    MockPins_SetPg(1);
    MockPins_SetStat(0);   /* STAT asserted means nothing without input power */
    tick_ok(0U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_NO_INPUT, Charger_GetState(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsPowerGood(&s_mon));
}

/* -------------------------------------------------------------------------- */
/* VBUS                                                                        */
/* -------------------------------------------------------------------------- */

static void test_vbus_present_tracks_level(void)
{
    MockPins_SetVbus(1);
    tick_ok(0U);
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_IsVbusPresent(&s_mon));

    MockPins_SetVbus(0);
    tick_ok(100U);
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsVbusPresent(&s_mon));
}

static void test_missing_vbus_reader_reports_not_present(void)
{
    Charger_Monitor mon;

    TEST_ASSERT_EQUAL(CHARGER_OK, Charger_Init(&mon, MockPins_IfaceNoVbus()));
    MockPins_SetVbus(1);   /* level is high, but there is no reader wired */
    TEST_ASSERT_EQUAL(CHARGER_OK, Charger_Tick(&mon, 0U));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsVbusPresent(&mon));
}

/* -------------------------------------------------------------------------- */
/* ALERT latch                                                                 */
/* -------------------------------------------------------------------------- */

static void test_alert_latches_on_falling_edge_until_cleared(void)
{
    tick_ok(0U);   /* ALERT idles HIGH */
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_AlertPending(&s_mon));

    MockPins_SetAlert(0);   /* gauge asserts */
    tick_ok(100U);
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_AlertPending(&s_mon));

    MockPins_SetAlert(1);   /* line released — latch must hold */
    tick_ok(200U);
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_AlertPending(&s_mon));

    Charger_ClearAlert(&s_mon);
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_AlertPending(&s_mon));

    /* A new assertion latches again. */
    MockPins_SetAlert(0);
    tick_ok(300U);
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_AlertPending(&s_mon));
}

static void test_alert_low_at_first_sample_latches(void)
{
    MockPins_SetAlert(0);   /* asserted before we ever sampled */
    tick_ok(0U);
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_AlertPending(&s_mon));
}

static void test_alert_held_low_does_not_relatch_after_clear(void)
{
    MockPins_SetAlert(0);
    tick_ok(0U);
    Charger_ClearAlert(&s_mon);

    /* Line still LOW (no new falling edge): stays cleared until it cycles. */
    tick_ok(100U);
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_AlertPending(&s_mon));

    MockPins_SetAlert(1);
    tick_ok(200U);
    MockPins_SetAlert(0);
    tick_ok(300U);
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_AlertPending(&s_mon));
}

/* -------------------------------------------------------------------------- */
/* Pin read failures                                                           */
/* -------------------------------------------------------------------------- */

static void test_pin_failure_degrades_to_unknown_and_recovers(void)
{
    MockPins_SetPg(0);
    MockPins_SetStat(0);
    tick_ok(0U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_CHARGING, Charger_GetState(&s_mon));

    MockPins_FailStat(1U);
    TEST_ASSERT_EQUAL(CHARGER_ERR_PIN, Charger_Tick(&s_mon, 100U));
    TEST_ASSERT_EQUAL(CHARGER_STATE_UNKNOWN, Charger_GetState(&s_mon));

    MockPins_FailStat(0U);
    tick_ok(200U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_CHARGING, Charger_GetState(&s_mon));
}

static void test_pin_failure_preserves_alert_latch(void)
{
    MockPins_SetAlert(0);
    tick_ok(0U);
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_AlertPending(&s_mon));

    MockPins_FailPg(1U);
    TEST_ASSERT_EQUAL(CHARGER_ERR_PIN, Charger_Tick(&s_mon, 100U));
    /* A transient read fault must not discard a pending gauge alert. */
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_AlertPending(&s_mon));
}

/* -------------------------------------------------------------------------- */
/* STAT fault-blink detector                                                   */
/* -------------------------------------------------------------------------- */

static void test_nominal_1hz_blink_declares_fault_on_third_edge(void)
{
    uint32_t t = 0U;

    MockPins_SetPg(0);

    /* Edge 1 (record) and edge 2 (first in-tolerance interval): not yet
     * a fault — one blink-like interval could still be a level change. */
    MockPins_SetStat(0);
    tick_ok(t);
    t = 500U;  MockPins_SetStat(1); tick_ok(t);
    t = 1000U; MockPins_SetStat(0); tick_ok(t);
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsFaultBlinkActive(&s_mon));
    TEST_ASSERT_EQUAL(CHARGER_STATE_CHARGING, Charger_GetState(&s_mon));

    /* Edge 3: second consecutive in-tolerance interval => fault blink. */
    t = 1500U; MockPins_SetStat(1); tick_ok(t);
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_IsFaultBlinkActive(&s_mon));
    TEST_ASSERT_EQUAL(CHARGER_STATE_FAULT, Charger_GetState(&s_mon));

    /* Blink continues: state stays FAULT through both half-periods. */
    t = 2000U; MockPins_SetStat(0); tick_ok(t);
    TEST_ASSERT_EQUAL(CHARGER_STATE_FAULT, Charger_GetState(&s_mon));
}

static void test_jittered_blink_within_tolerance_declares_fault(void)
{
    uint32_t t = 0U;

    MockPins_SetPg(0);
    MockPins_SetStat(0);
    tick_ok(t);

    /* Intervals 450 / 610 ms: both inside the 250-750 ms window. */
    t = 450U;  MockPins_SetStat(1); tick_ok(t);
    t = 1060U; MockPins_SetStat(0); tick_ok(t);
    t = 1500U; MockPins_SetStat(1); tick_ok(t);   /* interval 440 ms */
    TEST_ASSERT_EQUAL(CHARGER_STATE_FAULT, Charger_GetState(&s_mon));
}

static void test_fast_toggles_are_not_a_fault(void)
{
    uint32_t t = 0U;
    uint32_t i;

    MockPins_SetPg(0);
    MockPins_SetStat(0);
    tick_ok(t);

    /* 100 ms toggles (e.g. bus noise): every interval below tolerance. */
    for (i = 1U; i <= 10U; i++) {
        t = i * 100U;
        MockPins_SetStat((int)(i & 1U));
        tick_ok(t);
    }
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsFaultBlinkActive(&s_mon));
    TEST_ASSERT_NOT_EQUAL(CHARGER_STATE_FAULT, Charger_GetState(&s_mon));
}

static void test_slow_changes_are_not_a_fault(void)
{
    uint32_t t = 0U;

    MockPins_SetPg(0);
    MockPins_SetStat(0);
    tick_ok(t);

    /* Level changes 900 ms apart: ordinary charge-state transitions. */
    t = 900U;  MockPins_SetStat(1); tick_ok(t);
    t = 1800U; MockPins_SetStat(0); tick_ok(t);
    t = 2700U; MockPins_SetStat(1); tick_ok(t);
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsFaultBlinkActive(&s_mon));
    TEST_ASSERT_EQUAL(CHARGER_STATE_COMPLETE_OR_DISABLED,
                      Charger_GetState(&s_mon));
}

static void test_fault_clears_when_blink_stops(void)
{
    uint32_t t = 0U;

    MockPins_SetPg(0);
    (void)drive_blink(&t, 500U, 100U, 0, 3U);   /* 3 edges -> FAULT */
    TEST_ASSERT_EQUAL(CHARGER_STATE_FAULT, Charger_GetState(&s_mon));

    /* Fault condition removed: STAT settles LOW (charging again). Keep
     * sampling with no further edges until past the 1500 ms timeout. */
    MockPins_SetStat(0);
    tick_ok(t + 100U);      /* this is an edge (was HIGH after 3 toggles) */
    t += 100U;
    tick_ok(t + 500U);
    tick_ok(t + 1000U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_FAULT, Charger_GetState(&s_mon));
    tick_ok(t + 1600U);     /* > CHARGER_BLINK_TIMEOUT_MS since last edge */
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsFaultBlinkActive(&s_mon));
    TEST_ASSERT_EQUAL(CHARGER_STATE_CHARGING, Charger_GetState(&s_mon));
}

static void test_no_input_outranks_fault_blink(void)
{
    uint32_t t = 0U;

    MockPins_SetPg(1);   /* no input power at all */
    (void)drive_blink(&t, 500U, 100U, 0, 3U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_NO_INPUT, Charger_GetState(&s_mon));
}

/* -------------------------------------------------------------------------- */
/* Full charge-cycle scenario (multi-step state machine walk)                  */
/* -------------------------------------------------------------------------- */

static void test_full_charge_cycle_scenario(void)
{
    uint32_t t = 0U;

    /* 1) Unplugged: PG high, STAT high. */
    MockPins_SetPg(1);
    MockPins_SetStat(1);
    tick_ok(t);
    TEST_ASSERT_EQUAL(CHARGER_STATE_NO_INPUT, Charger_GetState(&s_mon));

    /* 2) Charger plugged in, charging: PG low, STAT low. */
    t = 5000U;
    MockPins_SetPg(0);
    MockPins_SetStat(0);
    MockPins_SetVbus(1);
    tick_ok(t);
    TEST_ASSERT_EQUAL(CHARGER_STATE_CHARGING, Charger_GetState(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_IsVbusPresent(&s_mon));

    /* 3) Battery fault develops: STAT blinks at 1 Hz, gauge asserts ALERT. */
    t = 10000U;
    MockPins_SetAlert(0);
    (void)drive_blink(&t, 500U, 100U, 0, 3U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_FAULT, Charger_GetState(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, Charger_AlertPending(&s_mon));

    /* 4) Fault serviced: alert cleared after reading the gauge registers. */
    Charger_ClearAlert(&s_mon);
    MockPins_SetAlert(1);

    /* 5) Blink stops with STAT settling HIGH: charge complete. */
    MockPins_SetStat(1);
    tick_ok(t + 100U);
    t += 100U;
    tick_ok(t + 1600U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_COMPLETE_OR_DISABLED,
                      Charger_GetState(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_AlertPending(&s_mon));

    /* 6) Charger unplugged again. */
    MockPins_SetPg(1);
    MockPins_SetVbus(0);
    tick_ok(t + 2000U);
    TEST_ASSERT_EQUAL(CHARGER_STATE_NO_INPUT, Charger_GetState(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsVbusPresent(&s_mon));
}

/* -------------------------------------------------------------------------- */
/* Accessor NULL-safety                                                        */
/* -------------------------------------------------------------------------- */

static void test_accessors_are_null_safe(void)
{
    TEST_ASSERT_EQUAL(CHARGER_STATE_UNKNOWN, Charger_GetState(NULL));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsPowerGood(NULL));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsVbusPresent(NULL));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_IsFaultBlinkActive(NULL));
    TEST_ASSERT_EQUAL_UINT8(0U, Charger_AlertPending(NULL));
    Charger_ClearAlert(NULL);   /* must simply not crash */
}

/* -------------------------------------------------------------------------- */
/* Runner                                                                      */
/* -------------------------------------------------------------------------- */

int main(void)
{
    UNITY_BEGIN();

    RUN_TEST(test_init_rejects_bad_params);
    RUN_TEST(test_state_unknown_before_first_tick);
    RUN_TEST(test_tick_rejects_null);

    RUN_TEST(test_pg_low_stat_low_decodes_charging);
    RUN_TEST(test_pg_low_stat_high_decodes_complete);
    RUN_TEST(test_pg_high_decodes_no_input_regardless_of_stat);

    RUN_TEST(test_vbus_present_tracks_level);
    RUN_TEST(test_missing_vbus_reader_reports_not_present);

    RUN_TEST(test_alert_latches_on_falling_edge_until_cleared);
    RUN_TEST(test_alert_low_at_first_sample_latches);
    RUN_TEST(test_alert_held_low_does_not_relatch_after_clear);

    RUN_TEST(test_pin_failure_degrades_to_unknown_and_recovers);
    RUN_TEST(test_pin_failure_preserves_alert_latch);

    RUN_TEST(test_nominal_1hz_blink_declares_fault_on_third_edge);
    RUN_TEST(test_jittered_blink_within_tolerance_declares_fault);
    RUN_TEST(test_fast_toggles_are_not_a_fault);
    RUN_TEST(test_slow_changes_are_not_a_fault);
    RUN_TEST(test_fault_clears_when_blink_stops);
    RUN_TEST(test_no_input_outranks_fault_blink);

    RUN_TEST(test_full_charge_cycle_scenario);

    RUN_TEST(test_accessors_are_null_safe);

    return UNITY_END();
}
